// TestAffectedMatchesModel checks the traversal and the exemption rule
// against every instance the model produced.
func TestAffectedMatchesModel(t *testing.T) {
	for _, c := range alloyGraphs {
		callers := make([][]int, 5)
		for _, e := range c.calls {
			callers[e[1]] = append(callers[e[1]], e[0])
		}
		got := Affected(callers, c.changed, Hops)
		if !reflect.DeepEqual(got, append([]int{}, c.affected...)) {
			t.Errorf("%s: Affected = %v, model says %v", c.name, got, c.affected)
		}
		var exempt []int
		for s := 0; s < 5; s++ {
			called := false
			for _, u := range callers[s] {
				called = called || u != s
			}
			if exemptRule(contains(c.exported, s), called, contains(c.mentioned, s)) {
				exempt = append(exempt, s)
			}
		}
		if !reflect.DeepEqual(append([]int{}, exempt...), append([]int{}, c.exempt...)) {
			t.Errorf("%s: exempt = %v, model says %v", c.name, exempt, c.exempt)
		}
	}
}

func contains(xs []int, x int) bool {
	for _, y := range xs {
		if y == x {
			return true
		}
	}
	return false
}
